"use strict";
import { createContext, useContext, useState } from "react";
export const DashContext = createContext(null);
export const DashContextProvider = ({ children }) => {
  const [expandCollapse, setExpandCollapse] = useState(false);
  return <DashContext.Provider value={{ expandCollapse, setExpandCollapse }}>{children}</DashContext.Provider>;
};
export const useDashContext = () => {
  const context = useContext(DashContext);
  if (!context) {
    throw new Error("useDashContext must be used within a DashContextProvider");
  }
  return context;
};
