"use strict";
import { PositionStatus, ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { Trans } from "react-i18next";
import { Flex, Text, useSporeColors } from "ui/src";
import { Shrink } from "ui/src/components/icons";
import { formatCurrencyAmount } from "utils/formatCurrencyAmount";
import { useGetRangeDisplay, usePositionDerivedInfo } from "components/Liquidity/hooks";
import { useState, useMemo } from "react";
import { ArrowsLeftRight } from "ui/src/components/icons/ArrowsLeftRight";
import { ClickableTamaguiStyle } from "theme/components/styles";
import { useUSDCPrice } from "uniswap/src/features/transactions/hooks/useUSDCPrice";
import { PollingInterval } from "uniswap/src/constants/misc";
import { areCurrenciesEqual } from "uniswap/src/utils/currencyId";
import { useLocalizationContext } from "uniswap/src/features/language/LocalizationContext";
import { NumberType } from "utilities/src/format/types";
import TokenDetails from "./TokenDetails";
import PositionRow from "./PositionRow";
const CurrencyDetails = ({
  position,
  isV3,
  getStatusColor
}) => {
  const [pricesInverted, setPricesInverted] = useState(false);
  const { priceOrdering } = usePositionDerivedInfo(position);
  const { maxPrice, minPrice, tokenASymbol, tokenBSymbol, isFullRange } = useGetRangeDisplay({
    priceOrdering,
    tickSpacing: position.tickSpacing,
    tickLower: position.tickLower,
    tickUpper: position.tickUpper,
    pricesInverted
  });
  const showRangeInfo = position.version === ProtocolVersion.V3 && priceOrdering.priceLower && priceOrdering.priceUpper;
  return <Flex row $md={{ flexDirection: "column", alignItems: "flex-start" }} gap={"$gap12"} alignItems="center">
      <Text variant="body4" color={"$neutral2"}>
        {formatCurrencyAmount(position.currency0Amount, 4)} {position.currency0Amount?.currency.symbol} +{" "}
        {formatCurrencyAmount(position.currency1Amount, 4)} {position.currency1Amount?.currency.symbol}
      </Text>

      <Flex row gap={"$gap8"} alignItems="center" flexWrap="wrap">
        {isV3 ? <>
            <Shrink size={18} color={getStatusColor()} />
            <Text variant="buttonLabel4" color={getStatusColor()}>
              {position?.status === PositionStatus.IN_RANGE ? <Trans i18nKey="common.withinRange" /> : position?.status === PositionStatus.OUT_OF_RANGE ? <Trans i18nKey="common.outOfRange" /> : "Unknown"}
            </Text>
          </> : <>
            <Shrink size={18} color={getStatusColor()} />
            <Text variant="buttonLabel4" color={getStatusColor()}>
              <Trans i18nKey="common.withinRange" />
            </Text>
          </>}
        {showRangeInfo && <Flex
    row
    gap="$gap4"
    alignItems="center"
    onPress={(e) => {
      e.preventDefault();
      e.stopPropagation();
      setPricesInverted((prevInverted) => !prevInverted);
    }}
    {...ClickableTamaguiStyle}
  >
            <Text variant="body4" color="$neutral2">
              {minPrice} - {maxPrice} {tokenASymbol}/{tokenBSymbol}
            </Text>
            <ArrowsLeftRight color="$neutral2" size="$icon.16" />
          </Flex>}
      </Flex>
    </Flex>;
};
export default function PoolLiquidityRewards({ poolGroup, isLoading }) {
  const colors = useSporeColors();
  const { formatCurrencyAmount: formatCurrencyAmount2 } = useLocalizationContext();
  if (isLoading) {
    return <Flex flexDirection="column" gap={"$gap12"}>
        <Flex
      style={{
        background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
      }}
      py={"$spacing24"}
      px={"$spacing20"}
      borderRadius={"$rounded12"}
      borderWidth={1}
      borderColor={"$surface3"}
      opacity={0.6}
    >
          <Flex row gap={"$gap12"} justifyContent="space-between">
            <TokenDetails isLoading={true} />
            <Flex flexDirection="column" gap={"$gap12"} justifyContent="center" alignItems="flex-end">
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Text variant="body3" fontSize={"$mdall"}>
                -
              </Text>
            </Flex>
          </Flex>
        </Flex>
      </Flex>;
  }
  if (!poolGroup) {
    return null;
  }
  const token0Symbol = poolGroup.representative.currency0Amount?.currency.symbol || "";
  const token1Symbol = poolGroup.representative.currency1Amount?.currency.symbol || "";
  const token0Currency = poolGroup.representative.currency0Amount?.currency;
  const token1Currency = poolGroup.representative.currency1Amount?.currency;
  const { price: price0 } = useUSDCPrice(token0Currency, PollingInterval.Normal);
  const { price: price1 } = useUSDCPrice(token1Currency, PollingInterval.Normal);
  const { totalToken0Amount, totalToken1Amount, totalUSDValue } = useMemo(() => {
    let totalToken0 = poolGroup.positions.reduce((sum, pos) => {
      const amount = pos.currency0Amount ? parseFloat(pos.currency0Amount.toSignificant(10)) : 0;
      return sum + amount;
    }, 0);
    let totalToken1 = poolGroup.positions.reduce((sum, pos) => {
      const amount = pos.currency1Amount ? parseFloat(pos.currency1Amount.toSignificant(10)) : 0;
      return sum + amount;
    }, 0);
    let usdValue = 0;
    if (price0 && token0Currency && areCurrenciesEqual(price0.baseCurrency, token0Currency)) {
      const price0Num = parseFloat(price0.toSignificant(6));
      usdValue += totalToken0 * price0Num;
    }
    if (price1 && token1Currency && areCurrenciesEqual(price1.baseCurrency, token1Currency)) {
      const price1Num = parseFloat(price1.toSignificant(6));
      usdValue += totalToken1 * price1Num;
    }
    return {
      totalToken0Amount: totalToken0,
      totalToken1Amount: totalToken1,
      totalUSDValue: usdValue > 0 ? usdValue : null
    };
  }, [poolGroup.positions, price0, price1, token0Currency, token1Currency]);
  const totalValue = totalUSDValue ? formatCurrencyAmount2({
    value: totalUSDValue,
    type: NumberType.FiatStandard
  }) : "-";
  return <Flex flexDirection="column" gap={"$gap12"}>
      {
    /* Pool Header - shown once */
  }
      <Flex
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
    py={"$spacing24"}
    px={"$spacing20"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    hoverStyle={{ borderColor: "$surface3Hovered" }}
  >
        <Flex
    row
    gap={"$gap12"}
    justifyContent="space-between"
    $md={{ flexDirection: "column", justifyContent: "flex-start" }}
  >
          <TokenDetails position={poolGroup.representative} />

          <Flex flexDirection="column" gap={"$gap24"} width={"unset"} $md={{ width: "100%" }}>
            <Flex
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $md={{ row: true, justifyContent: "space-between", mt: "$gap12" }}
  >
              <Text variant="body3" color={"$neutral2"}>
                Deposited
              </Text>
              <Flex flexDirection="column" alignItems="flex-end" gap={"$gap4"} $md={{ alignItems: "flex-start" }}>
                <Text variant="body3" fontSize={"$mdall"}>
                  {totalValue}
                </Text>
                <Text variant="body4" color={"$neutral2"}>
                  {totalToken0Amount.toFixed(4)} {token0Symbol}, {totalToken1Amount.toFixed(4)} {token1Symbol}
                </Text>
              </Flex>
            </Flex>

          </Flex>
        </Flex>
      </Flex>

      {
    /* Individual Positions */
  }
      {poolGroup.positions.map((position, index) => <Flex key={`${poolGroup.poolKey}-${index}`}>
          <PositionRow index={index} position={position} CurrencyDetails={CurrencyDetails} />
        </Flex>)}
    </Flex>;
}
